<template><view class="ending-poster" :class="{luminous}"><SceneBackdrop :src="background" :shade="luminous?.05:.2"/><view class="poster-vignette"/><AssetImage class="poster-crack" :src="uiAssets.decorations.crack" fit="contain"/><view class="poster-layout"><view class="poster-copy"><text class="section-label">{{id}} / {{luminous?'THE COMPLETE SELF':'A LIFE, REMEMBERED'}}</text><text class="poster-title">{{title}}</text><AssetImage class="poster-divider" :src="uiAssets.decorations.divider" fit="contain"/><text class="poster-quote">{{description}}</text><view class="poster-actions"><slot name="actions"/></view></view><AssetPanel class="poster-record" :variant="luminous?'light':'large'"><slot/></AssetPanel></view></view></template><script setup lang="ts">import SceneBackdrop from '../common/SceneBackdrop.vue';import AssetImage from '../common/AssetImage.vue';import AssetPanel from '../common/AssetPanel.vue';import {uiAssets} from '../../config/ui-assets';defineProps<{id:string;title:string;description?:string;background:string;luminous?:boolean}>()</script><style scoped>.ending-poster{position:relative;min-height:100svh}.poster-vignette{position:absolute;inset:0;background:linear-gradient(90deg,#08090b80,transparent 65%),linear-gradient(0deg,#08090bb3,transparent 65%)}.poster-crack{position:absolute;left:0;bottom:0;width:40%;height:40%;opacity:.1;mix-blend-mode:screen}.poster-layout{position:relative;z-index:20;display:grid;grid-template-columns:minmax(0,1fr) minmax(250px,24%);gap:8vw;align-items:end;min-height:100svh;padding:18vh 5vw 9vh}.poster-title{display:block;font:clamp(36px,5vw,78px)/1.3 'Songti SC','STSong',serif;color:#f4e7cc;margin:22px 0;text-shadow:0 2px 24px #0006}.poster-divider{width:220px;height:20px;opacity:.6}.poster-quote{display:block;font:clamp(15px,1.3vw,21px)/2 'Songti SC',serif;max-width:510px;margin:20px 0;color:#e5dfd0}.poster-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:35px}.poster-record{--panel-opacity:.18;max-height:70vh;overflow:auto;background:#08090b55}.luminous .poster-vignette{background:linear-gradient(0deg,#e9eedfcc,transparent 80%),linear-gradient(90deg,#e8e9d766,transparent 65%)}.luminous .poster-title{color:#304b42;text-shadow:0 1px 16px #fff8}.luminous .poster-quote{color:#344b40}.luminous .section-label{color:#6e7456}.luminous .poster-record{background:#f3efdfbb;--panel-opacity:.12}.luminous .poster-crack{opacity:.05}
